import { Badge } from "@/registry/bases/takumi/components/badge/badge";
import { PdfList } from "@/registry/bases/takumi/components/list/list";
import { PageFooter } from "@/registry/bases/takumi/components/page-footer/page-footer";
import { PageHeader } from "@/registry/bases/takumi/components/page-header/page-header";
import { Section } from "@/registry/bases/takumi/components/section/section";
import {
  Table,
  TableBody,
  TableCell,
  TableHeader,
  TableRow,
} from "@/registry/bases/takumi/components/table/table";
import { Text } from "@/registry/bases/takumi/components/text/text";
import {
  PdfcnThemeProvider,
  usePdfcnTheme,
} from "@/registry/bases/takumi/components/theme-provider";
import {
  Document,
  Page,
  StyleSheet,
  View,
} from "@/registry/bases/takumi/lib/pdf-primitives";
import type { PdfcnTheme } from "@/registry/types/pdf-themes";

import type { LessonPlanProps } from "./lesson-plan.types";
import { sampleLessonPlanData } from "./lesson-plan.types";

export const LessonPlanContent = ({ data }: { data: LessonPlanProps }) => {
  const theme = usePdfcnTheme();
  const accent = data.accentColor ?? theme.colors.primary;

  const styles = StyleSheet.create({
    badgeWrap: {
      flexDirection: "row",
      flexWrap: "wrap",
      gap: 4,
      marginTop: 3,
    },
    page: {
      backgroundColor: theme.colors.background,
      boxSizing: "border-box",
      color: theme.colors.foreground,
      minHeight: 841,
      padding: theme.spacing.page.marginTop,
      paddingBottom: theme.spacing.page.marginBottom,
      position: "relative",
    },
    reflectionLine: {
      borderBottomColor: theme.colors.border,
      borderBottomWidth: 1,
      height: 16,
    },
    sectionHeading: {
      fontSize: 9,
      fontWeight: "bold",
      marginBottom: 3,
    },
    twoColumn: {
      flexDirection: "row",
      gap: 15,
    },
  });

  return (
    <Document title={`Lesson Plan — ${data.lessonTitle}`}>
      <Page size="A4" style={styles.page}>
        <PageHeader
          marginBottom={12}
          rightSubText={`Teacher: ${data.teacherName} · ${data.duration}`}
          rightText={data.date}
          subtitle={`${data.subject} · ${data.gradeLevel}`}
          title={data.lessonTitle}
          variant="two-column"
        />

        {data.essentialQuestion && (
          <Section accentColor={accent} spacing="sm" variant="callout">
            <Text color="primary" noMargin style={styles.sectionHeading}>
              Essential Question
            </Text>
            <Text noMargin style={{ fontSize: 9.5, fontStyle: "italic" }}>
              &ldquo;{data.essentialQuestion}&rdquo;
            </Text>
          </Section>
        )}

        {data.objectives.length > 0 && (
          <Section spacing="sm">
            <Text
              color="mutedForeground"
              noMargin
              style={styles.sectionHeading}
              transform="uppercase"
            >
              Learning Objectives (SWBAT)
            </Text>
            <PdfList
              gap="xs"
              items={data.objectives.map((text) => ({ text }))}
              variant="numbered"
            />
          </Section>
        )}

        <Section spacing="sm" style={styles.twoColumn}>
          <View style={{ flex: 1 }}>
            <Text
              color="mutedForeground"
              noMargin
              style={styles.sectionHeading}
              transform="uppercase"
            >
              Standards Alignment
            </Text>
            {data.standards && data.standards.length > 0 ? (
              <View style={styles.badgeWrap}>
                {data.standards.map((std) => (
                  <Badge key={std} label={std} size="sm" variant="outline" />
                ))}
              </View>
            ) : (
              <Text color="mutedForeground" noMargin variant="xs">
                None specified
              </Text>
            )}
          </View>
          <View style={{ flex: 1 }}>
            <Text
              color="mutedForeground"
              noMargin
              style={styles.sectionHeading}
              transform="uppercase"
            >
              Materials &amp; Resources
            </Text>
            <PdfList
              gap="xs"
              items={data.materials.map((text) => ({ text }))}
              variant="bullet"
            />
          </View>
        </Section>

        <Section spacing="sm">
          <Text
            color="mutedForeground"
            noMargin
            style={styles.sectionHeading}
            transform="uppercase"
          >
            Lesson Sequence &amp; Timing
          </Text>
          <Table variant="grid" zebraStripe>
            <TableHeader>
              <TableRow header>
                <TableCell width="14%">Time</TableCell>
                <TableCell width="24%">Activity</TableCell>
                <TableCell width="42%">Description</TableCell>
                <TableCell width="20%">Notes</TableCell>
              </TableRow>
            </TableHeader>
            <TableBody>
              {data.sequence.map((step) => (
                <TableRow key={`${step.time}-${step.activity}`}>
                  <TableCell
                    style={{ fontSize: 8, fontWeight: 600 }}
                    width="14%"
                  >
                    {step.time}
                  </TableCell>
                  <TableCell
                    style={{ fontSize: 8, fontWeight: 600 }}
                    width="24%"
                  >
                    {step.activity}
                  </TableCell>
                  <TableCell style={{ fontSize: 8 }} width="42%">
                    {step.description}
                  </TableCell>
                  <TableCell
                    style={{ color: theme.colors.mutedForeground, fontSize: 8 }}
                    width="20%"
                  >
                    {step.notes ?? "—"}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </Section>

        {data.differentiation && data.differentiation.length > 0 && (
          <Section spacing="sm" variant="highlight">
            <Text
              color="mutedForeground"
              noMargin
              style={styles.sectionHeading}
              transform="uppercase"
            >
              Differentiation &amp; Diverse Learners
            </Text>
            <PdfList
              gap="xs"
              items={data.differentiation.map((text) => ({ text }))}
              variant="bullet"
            />
          </Section>
        )}

        <Section spacing="sm" style={styles.twoColumn}>
          <View style={{ flex: 1 }}>
            <Text
              color="mutedForeground"
              noMargin
              style={styles.sectionHeading}
              transform="uppercase"
            >
              Formative Assessment
            </Text>
            {data.assessment.formative &&
            data.assessment.formative.length > 0 ? (
              data.assessment.formative.map((item) => (
                <Text
                  key={item}
                  noMargin
                  style={{ marginBottom: 3 }}
                  variant="xs"
                >
                  • {item}
                </Text>
              ))
            ) : (
              <Text color="mutedForeground" noMargin variant="xs">
                Ongoing observation
              </Text>
            )}
          </View>
          <View style={{ flex: 1 }}>
            <Text
              color="mutedForeground"
              noMargin
              style={styles.sectionHeading}
              transform="uppercase"
            >
              Summative Assessment
            </Text>
            {data.assessment.summative &&
            data.assessment.summative.length > 0 ? (
              data.assessment.summative.map((item) => (
                <Text
                  key={item}
                  noMargin
                  style={{ marginBottom: 3 }}
                  variant="xs"
                >
                  • {item}
                </Text>
              ))
            ) : (
              <Text color="mutedForeground" noMargin variant="xs">
                None for this session
              </Text>
            )}
          </View>
        </Section>

        {data.homework && (
          <Section spacing="sm">
            <Text
              color="mutedForeground"
              noMargin
              style={styles.sectionHeading}
              transform="uppercase"
            >
              Homework Assignment
            </Text>
            <Text noMargin variant="xs">
              {data.homework}
            </Text>
          </Section>
        )}

        <Section spacing="sm">
          <Text
            color="mutedForeground"
            noMargin
            style={styles.sectionHeading}
            transform="uppercase"
          >
            Teacher Reflection
          </Text>
          {data.reflection ? (
            <Text noMargin style={{ fontStyle: "italic" }} variant="xs">
              {data.reflection}
            </Text>
          ) : (
            <View>
              <View style={styles.reflectionLine} />
              <View style={styles.reflectionLine} />
            </View>
          )}
        </Section>

        <PageFooter
          leftText={`${data.subject} · ${data.lessonTitle}`}
          pagePadding={25}
          rightText={`${data.teacherName} · ${data.date}`}
          sticky
        />
      </Page>
    </Document>
  );
};

export const LessonPlanDocument = ({
  data = sampleLessonPlanData,
  theme,
}: {
  data?: LessonPlanProps;
  theme?: PdfcnTheme;
}) => (
  <PdfcnThemeProvider theme={theme}>
    <LessonPlanContent data={data} />
  </PdfcnThemeProvider>
);

export default LessonPlanDocument;

export interface LessonSequenceItem {
  activity: string;
  description: string;
  notes?: string;
  time: string;
}

export interface LessonAssessment {
  formative?: string[];
  summative?: string[];
}

export interface LessonPlanProps {
  accentColor?: string;
  assessment: LessonAssessment;
  date: string;
  differentiation?: string[];
  duration: string;
  essentialQuestion?: string;
  gradeLevel: string;
  homework?: string;
  lessonTitle: string;
  materials: string[];
  objectives: string[];
  reflection?: string;
  renderingBase?: "takumi" | "forme";
  sequence: LessonSequenceItem[];
  standards?: string[];
  subject: string;
  teacherName: string;
}

export const sampleLessonPlanData: LessonPlanProps = {
  accentColor: "#7c3aed",
  assessment: {
    formative: ["Exit ticket", "Observation"],
    summative: ["Chapter quiz"],
  },
  date: "September 15, 2026",
  differentiation: [
    "Provide equation mats for visual learners",
    "Allow calculator use for students with processing difficulties",
  ],
  duration: "50 minutes",
  essentialQuestion:
    "How can we represent real-world relationships using linear equations?",
  gradeLevel: "8th Grade",
  homework: "Complete worksheet problems 11-20",
  lessonTitle: "Introduction to Linear Equations",
  materials: ["Graph paper", "Rulers", "Calculator", "Whiteboard markers"],
  objectives: [
    "Define linear equations",
    "Graph linear equations on a coordinate plane",
    "Solve simple linear equations",
  ],
  reflection:
    "Students grasped the concept of slope well. Need additional time on graphing negative coordinates next session.",
  sequence: [
    {
      activity: "Warm-up",
      description: "Review solving one-step equations",
      notes: "Individual work on whiteboards",
      time: "5 min",
    },
    {
      activity: "Introduction",
      description: "Define linear equations, show examples",
      notes: "Direct instruction with slides",
      time: "10 min",
    },
    {
      activity: "Guided Practice",
      description: "Work through 3 examples together",
      notes: "Pair-share problem #2",
      time: "15 min",
    },
    {
      activity: "Independent Practice",
      description: "Complete worksheet problems 1-10",
      notes: "Circulate for formative check",
      time: "15 min",
    },
    {
      activity: "Closure",
      description: "Exit ticket: solve one linear equation",
      notes: "Collect at door",
      time: "5 min",
    },
  ],
  standards: ["CCSS.MATH.8.EE.B.6", "CCSS.MATH.8.EE.C.7"],
  subject: "Mathematics",
  teacherName: "Ms. Johnson",
};
